 * (171,184,250) (216,212,251) (250,243,254)) inverted through the display pipeline (Neutral tone map x0.86 ->
 * sRGB -> grade sat 1.36 / contrast 1.15; qa/pilot05/wave6/foam/tools/pipe.py). Only t > 0.8 reaches white.
 * `soapT` = the shared view-space lighting (top-lit from the upper left, like the ref bubbles).
 */
const SOAP05_GLSL = /* glsl */ `
const vec3 SOAP_CREV = vec3(0.23, 0.22, 0.66);
vec3 soap05(float t) {
  t = clamp(t, 0.0, 1.0) * 5.0;
  vec3 c = mix(SOAP_CREV, vec3(0.26, 0.38, 0.84), clamp(t, 0.0, 1.0));
  c = mix(c, vec3(0.38, 0.54, 0.97), clamp(t - 1.0, 0.0, 1.0));
  c = mix(c, vec3(0.56, 0.63, 0.96), clamp(t - 2.0, 0.0, 1.0));
  c = mix(c, vec3(0.78, 0.79, 0.98), clamp(t - 3.0, 0.0, 1.0));
  return mix(c, vec3(1.05, 1.03, 1.08), clamp(t - 4.0, 0.0, 1.0));
}
float soapT(vec3 Nv) {
  vec3 Lv = normalize(vec3(-0.35, 0.8, 0.5));
  float wrap = clamp(dot(Nv, Lv) * 0.55 + 0.5, 0.0, 1.0);
  float up = clamp(Nv.y * 0.5 + 0.5, 0.0, 1.0);
  return smoothstep(0.1, 0.8, wrap * 0.6 + up * 0.4);
}
`;

const BERM_VERT = /* glsl */ `
attribute vec3 aFoam;    // x = e (units outward from the stream edge), y = s, z = side (-1 / 1)
uniform float uTime;
varying vec3 vFoam;
varying vec3 vPosW;
varying vec3 vNormalW;
#include <fog_pars_vertex>
void main() {
  // gentle breathing of the lather (never at the water line)
  float k = smoothstep(-0.2, 0.3, aFoam.x);
  vec3 p = position + normal * (0.03 * k * sin(uTime * 1.6 + aFoam.y * 2.1 + aFoam.z * 3.0));
  vec4 wp = modelMatrix * vec4(p, 1.0);
  vPosW = wp.xyz;
  vNormalW = normalize(mat3(modelMatrix) * normal);
  vFoam = aFoam;
  vec4 mvPosition = viewMatrix * wp;
  gl_Position = projectionMatrix * mvPosition;
  #include <fog_vertex>
}
`;

const BERM_FRAG = /* glsl */ `
uniform float uTime;
uniform vec2 uOutro;     // amount, chamber start s
uniform vec3 uLightDir;
uniform vec4 uSt05;      // wave 7: 05 soap shading weight ramps in s0..s1, out s2..s3 (= bermScale05)
#ifdef M05BERM
uniform float uRide05;   // m05berm: ride factor (0 at the locked 05 checkpoint, 1 after 2 u of riding)
#endif
varying vec3 vFoam;
varying vec3 vPosW;
varying vec3 vNormalW;
#include <fog_pars_fragment>
${NOISE_GLSL}
${FRAG_FX_GLSL}
${SOAP05_GLSL}
#ifdef M05BANK
// m05bank (Screen 05 round 14): one layer of piled foam bubbles in cell units: x = dome height (0 between bubbles),
// y = crease width f2 - f1 (0 on the crease between two bubbles), zw = offset from this point to the bubble's centre
vec4 bankCell(vec2 p) {
  vec2 ip = floor(p), fp = fract(p);
  float f1 = 8.0, f2 = 8.0, br = 0.6;
  vec2 best = vec2(0.0);
  for (int yy = -1; yy <= 1; yy++) for (int xx = -1; xx <= 1; xx++) {
    vec2 g = vec2(float(xx), float(yy));
    vec2 h = fract(sin(vec2(dot(ip + g, vec2(127.1, 311.7)), dot(ip + g, vec2(269.5, 183.3)))) * 43758.5453);
    vec2 dv = g + 0.15 + 0.7 * h - fp;
    float dd = dot(dv, dv);
    if (dd < f1) { f2 = f1; f1 = dd; best = dv; br = 0.58 + 0.24 * fract(h.x * 7.13 + h.y * 3.1); } else if (dd < f2) { f2 = dd; }
  }
  f1 = sqrt(f1); f2 = sqrt(f2);
  float q = f1 / br;
  return vec4(sqrt(max(1.0 - q * q, 0.0)), f2 - f1, best);
}
#endif
void main() {
  float s = vFoam.y;
  #ifdef PROJ05
  // ?proj05=1: the approved picture's foam is baked into the 05 river texture, so the lather sheet steps aside on 05
  // (dithered over 3 u at both joins; 04 / 06 keep their berm)
  float pjIn = smoothstep(uSt05.y, uSt05.y + 3.0, s) * (1.0 - smoothstep(uSt05.z - 3.0, uSt05.z, s));
  #ifdef M05BERM
  pjIn *= 1.0 - uRide05;     // m05berm (Screen 05 round 10): the lather bank comes back while swimming
  #endif
  if (pjIn > 0.999 || fract(sin(dot(floor(gl_FragCoord.xy), vec2(12.9898, 78.233))) * 43758.5453) < pjIn) discard;
  #endif
  if (uOutro.x > 0.0 && s > uOutro.y - 2.0) {
    float n = vnoise(vec2(vFoam.x * 3.0, s * 0.35)) * 0.7 + 0.3;
    if (n < uOutro.x * 1.15) discard;
  }
  vec2 p = vec2(vFoam.x * vFoam.z * 1.1, s - uTime * 0.25);
  // detail fade with distance (cells per pixel)
  float fw = max(fwidth(p.x), fwidth(p.y));
  float k1 = 1.0 - smoothstep(0.12, 0.3, fw * 1.6);
  float k2 = 1.0 - smoothstep(0.12, 0.3, fw * 3.8);
  float c1 = mix(0.45, cells(p * 1.6), k1);
  #ifdef LOW_Q
  float c2 = c1;
  #else
  float c2 = mix(0.45, cells(p * 3.8 + 11.0), k2);
  #endif
  // bubble domes: bright cell centres, deep crevices between bubbles
  float bub = (1.0 - c1 * c1) * 0.6 + (1.0 - c2 * c2) * 0.4;
  vec3 N0 = normalize(vNormalW);
  if (!gl_FrontFacing) N0 = -N0;
  #ifdef LOW_Q
  vec3 N = N0;
  #else
  vec3 N = bumpNormal(vPosW, N0, bub * 0.1);
  #endif
  #ifdef M05BANK
  // m05bank: the bank as a pile of round foam bubbles, world-anchored and still (the painted banks do not drift); cells
  // 0.3 u (bubbles ≈ 0.18 … 0.25 u across) with small bubbles on them; fades out where a cell is under ≈ 5 px
  vec2 bq = vec2(vFoam.x * vFoam.z, s) / 0.30;
  vec4 bkB = bankCell(bq);
  #ifdef LOW_Q
  vec4 bkS = vec4(0.6, 1.0, 0.0, 0.0);
  #else
  vec4 bkS = bankCell(bq * 2.4 + 7.3);
  #endif
  // (05 only: fades out over the stage's last unit, the 06 bank keeps its own look)
  float bkK = uRide05 * (1.0 - smoothstep(0.12, 0.25, max(fwidth(bq.x), fwidth(bq.y)))) * (1.0 - smoothstep(uSt05.z, uSt05.z + 1.0, s));
  float bkH = bkB.x * (0.8 + 0.2 * bkS.x);
  vec3 Nb = bumpNormal(vPosW, N0, bkH * 0.16);
  #ifdef M05BANKCUT
  // seam: keep / drop whole bubbles by where their centre lies (ca at the centre from the local gradient of ca over the
  // cell coordinates) instead of the flat plane cutting through them (the early clip runs 0.45 u past the plane)
  {
    vec3 bcd = vPosW - uClip05P;
    float bca = dot(bcd, uClip05N);
    vec2 jx = dFdx(bq), jy = dFdy(bq);
    float cx = dFdx(bca), cy = dFdy(bca);
    float jd = jx.x * jy.y - jx.y * jy.x;
    vec2 gca = abs(jd) > 1e-9 ? vec2(jy.y * cx - jx.y * cy, jx.x * cy - jy.x * cx) / jd : vec2(0.0);
    float caC = bca + dot(gca, bkB.zw);
    bool bLive = dot(uClip05N, uClip05N) > 0.5 && bca > -3.0 && bca < 40.0 && length(bcd - bca * uClip05N) < 9.0;
    if (bLive && (caC > 0.0 || (bca > 0.0 && bkB.x <= 0.0))) discard;
  }
  #endif
  #endif
  vec3 L = normalize(uLightDir);
  vec3 V = normalize(cameraPosition - vPosW);
  float diff = 0.55 + 0.45 * max(dot(N, L), 0.0);
  vec3 white = vec3(1.0, 1.0, 1.0);
  vec3 lav = vec3(0.7, 0.68, 0.98);
  vec3 col = mix(lav, white, 0.3 + 0.7 * clamp(N.y * 0.5 + 0.5, 0.0, 1.0)) * diff;
  col = mix(col, lav * 0.8, smoothstep(0.6, 0.95, c1) * 0.7 * k1);
  col = mix(col, lav * 0.9, smoothstep(0.65, 0.95, c2) * 0.4 * k2);
  // tiny pores (open bubbles)
  #ifndef LOW_Q
  vec2 pp = p * 7.0 + 5.0;
  float pc = cells(pp);
  float kp = 1.0 - smoothstep(0.1, 0.25, fw * 7.0);
  col = mix(col, vec3(0.58, 0.56, 0.88), (1.0 - smoothstep(0.1, 0.2, pc)) * step(0.62, hash12(floor(pp))) * 0.75 * kp);
  #endif
  float spec = pow(max(dot(reflect(-V, N), L), 0.0), 28.0);
  float fres = pow(1.0 - clamp(dot(N, V), 0.0, 1.0), 3.0);
  col += vec3(1.0) * spec * 0.45 + iridescent(fres * 1.4 + c1 * 0.6) * fres * 0.18;
  col *= 0.96;
  // 05 (wave 7): the low rim under the puffs reads as small piled soap bubbles: white only on the cell
  // tops, periwinkle bodies, blue-violet crevices between the cells (ref 05 rim)
  float k05 = smoothstep(uSt05.x, uSt05.y, s) * (1.0 - smoothstep(uSt05.z, uSt05.w, s));
  // 05: the bank stops just past its bubble crest with a scalloped (cell) edge, so the purple wall shows right above
  // the rim instead of a pale lather slope (ref 05; e is the raw offset outward from the stream edge)
  #ifdef M05BANK
  // m05bank: the crest ends along the bubble tops — toward the outer edge only the higher part of each bubble remains
  // (scalloped by the bubbles themselves), so the purple wall shows above / between them
  float bkE = mix(0.3 + 0.45 * (1.0 - c1), 0.75, bkK);
  if (vFoam.x > mix(9.0, bkE, k05)) discard;
  if (k05 * bkK > 0.0 && bkB.x < 0.9 * bkK * smoothstep(0.2, 0.65, vFoam.x)) discard;
  #else
  if (vFoam.x > mix(9.0, 0.3 + 0.45 * (1.0 - c1), k05)) discard;
  #endif
  if (k05 > 0.0) {
    vec3 Nv = normalize((viewMatrix * vec4(N, 0.0)).xyz);
    float t5 = soapT(Nv) * 0.55 + 0.45 * mix(0.55, bub, max(k1, 0.3)) - 0.1;
    t5 -= smoothstep(0.55, 0.95, c1) * 0.45 * k1 + smoothstep(0.62, 0.95, c2) * 0.25 * k2;
    vec3 c5 = soap05(t5);
    #ifndef LOW_Q
    c5 = mix(c5, SOAP_CREV, (1.0 - smoothstep(0.1, 0.2, pc)) * step(0.62, hash12(floor(pp))) * 0.7 * kp);
    #endif
    c5 += vec3(1.0) * spec * 0.3;
    #ifdef M05BANK
    // m05bank: piled-bubble shading as the bank lumps (BANK_BUB_FRAG): key light from the upper left, white caps only on
    // the lit tops, periwinkle bodies, blue-violet creases and gaps between the bubbles, small bubbles on the big ones
    vec3 Nvb = normalize((viewMatrix * vec4(Nb, 0.0)).xyz);
    float tb = 0.52 + 0.62 * dot(Nvb, normalize(vec3(-0.4, 0.85, 0.35))) - (1.0 - bkB.x) * 0.45;
    tb -= 0.32 * (1.0 - smoothstep(0.0, 0.08, bkB.y)) + 0.1 * (1.0 - smoothstep(0.0, 0.07, bkS.y)) * bkB.x;
    tb += 0.08 * (bkS.x - 0.5);
    tb = 0.12 + 0.95 * smoothstep(0.38, 1.12, tb);
    vec3 cb = soap05(tb);
    cb = mix(cb, vec3(1.0, 0.97, 1.07), smoothstep(0.75, 1.0, tb) * 0.3);
    cb += vec3(1.0) * pow(max(dot(reflect(-V, Nb), L), 0.0), 24.0) * 0.25;
    c5 = mix(c5, cb, bkK);
    #endif
    col = mix(col, c5, k05);
  }
  gl_FragColor = vec4(col, 1.0);
  ${FRAG_TAIL}
}
`;

